import std.io

pub type AppError = Failed(String)

record CountIter { i: Int64, hi: Int64 }

impl Iterator<Int64> for CountIter {
    pub fn next(mut self) -> Option<Int64> {
        if self.i >= self.hi { return None }
        let v = self.i
        self.i = self.i + 1
        return Some(v)
    }
}

record Range2 { n: Int64 }

impl Iterable<Int64> for Range2 {
    type Iter = CountIter
    pub fn iterator(self) -> CountIter {
        return CountIter { i: 0, hi: self.n }
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let three = Range2 { n: 3 }

    let c = three.iterator().count()
    if c == 3 { io.println("count-ok") } else { io.println("count-bad") }

    let s = three.iterator().fold(0, |acc, x| acc + x)
    if s == 3 { io.println("fold-ok") } else { io.println("fold-bad") }

    let a = three.iterator().any(|x| x > 1)
    if a { io.println("any-ok") } else { io.println("any-bad") }

    let na = three.iterator().any(|x| x > 9)
    if na { io.println("any-miss-bad") } else { io.println("any-miss-ok") }

    let b = three.iterator().all(|x| x <= 2)
    if b { io.println("all-ok") } else { io.println("all-bad") }

    let nb = three.iterator().all(|x| x < 2)
    if nb { io.println("all-miss-bad") } else { io.println("all-miss-ok") }

    let r = three.iterator().reduce(|p, q| p + q)
    match r {
        Some(v) => { if v == 3 { io.println("reduce-ok") } else { io.println("reduce-bad") } }
        None => { io.println("reduce-none") }
    }

    let f = three.iterator().find(|x| x > 1)
    match f {
        Some(v) => { if v == 2 { io.println("find-ok") } else { io.println("find-bad") } }
        None => { io.println("find-none") }
    }

    let g = three.iterator().find(|x| x > 9)
    match g {
        Some(v) => { io.println("find-miss-bad") }
        None => { io.println("find-miss-ok") }
    }

    let zero = Range2 { n: 0 }
    let zc = zero.iterator().count()
    if zc == 0 { io.println("empty-count-ok") } else { io.println("empty-count-bad") }

    let zr = zero.iterator().reduce(|p, q| p + q)
    match zr {
        Some(v) => { io.println("empty-reduce-some-bad") }
        None => { io.println("empty-reduce-none-ok") }
    }

    let zf = zero.iterator().find(|x| x > 0)
    match zf {
        Some(v) => { io.println("empty-find-some-bad") }
        None => { io.println("empty-find-none-ok") }
    }

    return Ok(())
}
